NEW["T60"] = dict(id="T60", task="4.1", stem=
"A company bought a Regional Reserved Instance for a Linux EC2 instance type. Later it moves its matching instance from one Availability Zone to another in the same Region, keeping the same instance type. What happens to the discount?",
choices=[("It keeps applying, because a Regional Reserved Instance covers matching usage in any Availability Zone of its Region",1),("It stops applying, because every Reserved Instance is tied to one Availability Zone",0),("The Reserved Instance moves the instance back to the original Availability Zone",0),("It applies only after the company exchanges the Reserved Instance for a new one",0)],
expl="A Reserved Instance is a billing discount on matching running usage, not a machine. Regional scope means the discount follows matching instances to any Availability Zone in the Region (and, for Linux on shared tenancy, to other sizes in the family); only a zonal Reserved Instance is tied to one zone, in exchange for reserving capacity there.",
links=[("11-paying-for-aws/02-purchasing-options.md","Reserved Instances: a billing discount on a matching configuration")])
